  dev_front_lock: ["سامنے کے دروازے کا تالا", "قفل الباب الأمامي", "सामने के दरवाज़े का ताला", "Cerradura de la puerta principal", "Serrure de la porte d'entrée"],
  dev_back_lock: ["پچھلے دروازے کا تالا", "قفل الباب الخلفي", "पीछे के दरवाज़े का ताला", "Cerradura de la puerta trasera", "Serrure de la porte arrière"],
  dev_living_light: ["لِونگ روم کی لائٹ", "إضاءة غرفة المعيشة", "लिविंग रूम की लाइट", "Luz del salón", "Lumière du salon"],
  dev_kitchen_light: ["باورچی خانے کی لائٹ", "إضاءة المطبخ", "रसोई की लाइट", "Luz de la cocina", "Lumière de la cuisine"],
  dev_garage: ["گیراج کا دروازہ", "باب المرآب", "गैराज का दरवाज़ा", "Puerta del garaje", "Porte du garage"],
